const advanced={resonance:['nuclearSpin','hyperfinePerp','hyperfineParallel','nuclearGamma','frequencyMin','frequencyMax','frequencyPoints','fieldMax','fieldPoints'],andreev:['energyMin','energyMax','samples','eta'],spectra:['F0','F2','F4','pdF0','pdF2','pdG1','pdG3','energyMin','energyMax','samples']};
export const defaultInputs=Object.fromEntries(Object.entries(fields).map(([key,list])=>[key,Object.fromEntries(list.map(f=>[f[0],f[2]]))]));
export const modelNotes={resonance:"Independent model given effective spin parameters. g, D, E, A are not automatically derived from the existing Kanamori results without SOC; the absorption intensity is the relative magnetic dipole intensity.",andreev:"A one-dimensional noninteracting coherent NS junction, with specified s-wave pairing in the right electrode. Conductance includes both physical spins at zero temperature with fixed potential; self-consistent gaps, finite-bias potentials and Josephson currents are not calculated.",spectra:"p⁶d⁸/d⁹ → p⁵d⁹/d¹⁰. Complete Slater with SOC does not contain ligand charge transfer. Energy is calibrated to the center of gravity of the final state, intensities omit common radial factors, and are not material fits or absolute absorption edges."};
const select=(id,rows,value)=>`<select id="${id}">${rows.map(([v,t])=>`<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(t)}</option>`).join('')}</select>`;
export function controlsHTML(module,input){const render=([key,label,def,min,max,step])=>`<label>${esc(label)}${Array.isArray(min)?select('spx-'+key,min,input[key]??def):`<input id="spx-${key}" type="number" min="${min}" max="${max}" step="${step}" value="${esc(input[key]??def)}">`}</label>`;return fields[module].filter(f=>!advanced[module].includes(f[0])).map(render).join('')+`<details class="spx-advanced"><summary>${module==='spectra'?"Slater integration and sampling settings":module==='resonance'?"Core spin, hyperfine and sampling settings":"sampling and numerical broadening"}</summary><div>${fields[module].filter(f=>advanced[module].includes(f[0])).map(render).join('')}</div></details><p class="obs-small">${esc(modelNotes[module])}</p>`;}
export function readControls(module,root,previous={}){const out={...previous};for(const [key,,def]of fields[module]){const v=root.querySelector('#spx-'+key).value;if(typeof def==='number'){if(!String(v).trim()||!Number.isFinite(Number(v)))throw Error("Numeric parameters must be limited numbers and cannot be left blank.");out[key]=Number(v);}else out[key]=v;}return out;}
function checksHTML(r){return `<details class="qm-checks"><summary>numerical verification and derivation basis</summary>${table(["check item","Result"],Object.entries(r.checks||{}).filter(([,v])=>['number','string','boolean'].includes(typeof v)).map(([k,v])=>[k,typeof v==='number'?num(v):typeof v==='boolean'?(v?"Yes":"No"):v]))}${(r.derivation||[]).map(s=>typeof s==='string'?`<p>${esc(s)}</p>`:`<h4>${esc(s.title)}</h4><div class="obs-formula">${esc(s.formula)}</div><p>${esc(s.text||s.explanation)}</p>`).join('')}</details>`;}
const series=(xs,ys,label)=>({label,points:xs.map((x,i)=>[x,ys[i]])});
function orientation(r){const p=v=>[300+125*(v[0]+.45*v[1]),180-125*(v[2]-.3*v[1])];return `<svg class="spx-orientation" viewBox="0 0 600 350" role="img" aria-label="Crystal main axis, static magnetic field and microwave magnetic field direction"><title>direction projection diagram; the dotted line is the main axis of the crystal</title>${[[[1,0,0],'x'],[[0,1,0],'y'],[[0,0,1],'z']].map(([v,l])=>{const q=p(v);return `<path d="M300 180L${q[0]} ${q[1]}" stroke="#9daea2" stroke-dasharray="5 4"/><text x="${q[0]+8}" y="${q[1]}">${l}</text>`;}).join('')}${[[r.selection.fieldDirection,"Static magnetic field B",'#247b65'],[r.selection.microwaveDirection,"Microwave B₁",'#b17a31']].map(([v,t,c])=>{const q=p(v);return `<path d="M300 180L${q[0]} ${q[1]}" stroke="${c}" stroke-width="5"/><circle cx="${q[0]}" cy="${q[1]}" r="6" fill="${c}"/><text x="${q[0]-55}" y="${q[1]-18}" fill="${c}">${svgMathText(t)}</text>`;}).join('')}<text x="300" y="326" text-anchor="middle">${esc(modelNotes.resonance.split('。')[0])}</text></svg>`;}
function junction(r){const n=r.device.sites.length,x=i=>125+i*340/Math.max(1,n-1);return `<svg class="spx-junction" viewBox="0 0 660 220" role="img" aria-label="Limited device connected between normal metal and superconducting electrode"><rect x="12" y="58" width="75" height="88" rx="10" fill="#d3e6dc"/><rect x="510" y="58" width="138" height="88" rx="10" fill="#e8dded"/><text x="18" y="40">normal electrode</text><text x="520" y="40">${r.parameters.gap?"superconducting electrode":"normal electrode"}</text><text x="524" y="180">Δ=${num(r.parameters.gap)} eV</text><path d="M87 104H510" stroke="#718a7c" stroke-width="3"/>${r.device.sites.map(s=>`<circle cx="${x(s.index)}" cy="104" r="${n>20?5:8}" fill="${Math.abs(s.onsite)>1e-10?'#b17a31':'#247b65'}"><title>grid point ${s.index}; in position ${num(s.onsite)} eV</title></circle>`).join('')}<text x="280" y="180" text-anchor="middle">Normal scattering area · ${n} grid point</text></svg>`;}
export function resultHTML(module,r){let out='';if(module==='resonance'){const s=r.selection;out=table(["Current results","Value"],[["spin space dimension",r.dimension],["Strongest transition frequency (GHz)",num(s.dominantFrequency)],["positive frequency absorption total weight",num(s.totalWeight)],["direction valid g",num(s.effectiveG)]])+orientation(r)+`<h3>magnetic dipole absorption spectrum</h3>`+curve([series(r.spectrum.frequencies,r.spectrum.absorption,"Current direction and polarization")],{xLabel:"Microwave frequency (GHz)",yLabel:"relative absorption density (1/GHz)"})+`<h3>sweep energy level</h3><label>The lowest energy level number displayed${select('spx-level-count',[[8,"Up to 8 items"],[16,"Up to 16 items"],[36,"all energy levels"]],8)}</label><div id="spx-levels"></div>`+notes(["Each field point is sorted by energy; the connection is for reading and does not mean tracking the same quantum state. Degenerate transitions are summed over subspaces to avoid any eigenvectors changing their intensity."])+`<details><summary>Transition and occupation under the current field</summary>${table(["First group → Last group","frequency (GHz)","matrix element strength","thermal occupancy difference","absorption weight"],[...s.transitions].sort((a,b)=>b.weight-a.weight).slice(0,30).map(t=>[`${t.from} → ${t.to}`,num(t.frequency),num(t.strength),num(t.populationDifference),num(t.weight)]))}<p>displays the strongest up to 30 transitions; see JSON for complete results.</p>${table(["relative energy (GHz)","Degeneracy","group total occupancy"],s.groups.map(g=>[num(g.relativeEnergy),g.degeneracy,num(g.population)]))}</details>`;
 }else if(module==='andreev'){const s=r.selection;out=table(["Current results","Value"],[["Normal reflection of electrons Rₑₑ",num(s.normalReflection)],["Andreev Reflection Rₕₑ",num(s.andreevReflection)],["Quasi-particle transmission",num(s.quasiparticleTransmission)],["conductance G（e²/h, including two spins)",num(s.conductanceQuantum)],["conductivity G (S)",num(s.conductanceSiemens)],["value η absorption",num(s.regulatorAbsorption)],["Result status",s.defined?(s.numericallyResolved?"Current diagnosis passed":"needs to verify the numerical error"):"Please take the adjacent limit at the threshold"]])+notes([s.reason].filter(Boolean))+junction(r)+`<h3>Electron and hole channels</h3>`+curve([['normalReflection','Rₑₑ'],['andreevReflection','Rₕₑ'],['quasiparticleTransmission',"Quasi-particle transmission"]].map(([k,l])=>series(r.scan.energies,r.scan.rows.map(x=>x[k]),l)),{xLabel:"Relative Fermi energy E (eV)",yLabel:"Probability of each incident electron channel"})+curve([series(r.scan.energies,r.scan.rows.map(x=>x.conductanceQuantum),"NS physical conductivity G"),series(r.scan.energies,r.scan.normalConductanceQuantum,"same device Δ=0 reference")],{xLabel:"Energy E (eV)",yLabel:"G（e²/h, including two spins)"})+`<h3>Local spectrum of current energy</h3>`+(s.electronLDOS?.length?curve([series(s.electronLDOS.map((_,i)=>i),s.electronLDOS,"Electronic LDOS"),series(s.holeLDOS.map((_,i)=>i),s.holeLDOS,"Hole LDOS")],{xLabel:"scattering area grid points",yLabel:"Single BdG block LDOS (1/eV)"}):"<p>The local spectrum is not displayed at the threshold, please change the observation energy slightly.</p>");
 }else{const g=r.ground;out=table(["Current results","Value"],[["initial state dimension",r.dimensions.initial],["final state dimension",r.dimensions.final],["ground state degeneracy",g.degeneracy],["ground state ⟨S²⟩",num(g.S2)],["ground state ⟨L²⟩",num(g.L2)],["ground state ⟨S_z⟩",num(g.Sz)],["ground state ⟨L_z⟩",num(g.Lz)]])+`<h3>Polarization Resolution XAS</h3>`+curve([series(r.spectrum.energies,r.spectrum.selected,"Selected polarization"),series(r.spectrum.energies,r.spectrum.isotropic,"Average in all directions")],{xLabel:"Absorbed energy relative to the center of gravity of the final state (eV)",yLabel:"relative absorption density"})+`<label>comparison channel${select('spx-spectrum-view',[['linear',"x, y, z linear polarization"],['circular',"± circular polarization"],['difference',"circular/linear polarization difference spectrum"]],'linear')}</label><div id="spx-spectrum-detail"></div>`+notes(["SOC Lower S and L are generally not good quantum numbers, and the table above shows the expected values. Relative energy can be negative, not negative absolute photon energy. The intensity of polarized light includes matrix elements and thermal occupancy, and is not only determined by energy level differences."])+`<details><summary>beginning and end multiplet , occupation and strong transition</summary>${table(["Initial state relative energy (eV)","Degeneracy","hot occupation",'⟨S²⟩','⟨L²⟩'],r.initialLevels.map(s=>[num(s.energy),s.degeneracy,num(s.population),num(s.S2),num(s.L2)]))}${table(["final state relative center of gravity energy (eV)","Degeneracy"],r.finalLevels.map(s=>[num(s.energy),s.degeneracy]))}${table(["First group → Last group","relative transition energy (eV)","Strength"],r.transitions.slice(0,60).map(t=>[`${t.initialGroup} → ${t.finalGroup}`,num(t.energy),num(t.strength)]))}${table(["3d track","ground state average occupation"],['xy','yz','xz','x²−y²','3z²−r²'].map((l,i)=>[l,num(g.orbitalOccupations[i])]))}</details>`;}
 return out+notes(r.warnings)+checksHTML(r)+sources(r.sources);
}
export function bindResult(module,r,root){const $=s=>root.querySelector(s);if(module==='resonance'){const draw=()=>{const n=Math.min(Number($('#spx-level-count').value),r.dimension);$('#spx-levels').innerHTML=curve(Array.from({length:n},(_,i)=>series(r.fieldScan.fields,r.fieldScan.energies.map(e=>e[i]),"energy level "+(i+1))),{xLabel:"Static magnetic field (T)",yLabel:"H/h energy (GHz)"});};$('#spx-level-count').onchange=draw;draw();}else if(module==='spectra'){const draw=()=>{const mode=$('#spx-spectrum-view').value,ks=mode==='linear'?[['x',"x polarization"],['y',"y polarization"],['z',"z polarization"]]:mode==='circular'?[['plus',"+ circular polarization"],['minus',"− circular polarization"]]:[['xmcd','I₊ − I₋'],['xld','I_z − I_x']];$('#spx-spectrum-detail').innerHTML=curve(ks.map(([k,l])=>series(r.spectrum.energies,r.spectrum[k],l)),{xLabel:"relative absorption energy (eV)",yLabel:mode==='difference'?"poor relative absorption":"relative absorption density"});};$('#spx-spectrum-view').onchange=draw;draw();}}
